import './Login.css';
import NavigationBar from './NavigationBar';
import Container from 'react-bootstrap/Container';
import Row from 'react-bootstrap/Row';
import Col from 'react-bootstrap/Col';
import { Link } from 'react-router-dom';
import { useState, useEffect } from 'react';
import axios from 'axios';
import Comment from './Comment';

function Home() {

    const [posts, setPosts] = useState([]);
    const [editingPost, setEditingPost] = useState(null);
    const userId = localStorage.getItem('userId');
    const token = localStorage.getItem("authToken");
    
    // Create a current user object from localStorage
    const currentUser = {
      id: localStorage.getItem("userId"),
      username: localStorage.getItem("username"),
    };
  
    const fetchPosts = async () => {
      try {
        const response = await axios.get("http://localhost:6543/api/posts", {
            headers: { Authorization: `Bearer ${token}` }
        });
        setPosts(response.data);
      } catch (err) {
        console.error("Error fetching posts", err);
      }
    };
  
    useEffect(() => {
      fetchPosts();
    }, []);

    const handleDelete = async (postId, postUserId) => {
        if (Number(userId) !== postUserId) {
          alert("You are not authorized to delete this post.");
          return;
        }
        try {
          await axios.delete(`http://localhost:8080/api/posts/${postId}/delete`, {
            headers: { Authorization: `Bearer ${token}` }
          });
          fetchPosts();
        } catch (error) {
          console.error(error);
        }
      };
    
      const handleEdit = (post) => {
        if (Number(userId) !== post.user.id) {
          alert("You are not authorized to edit this post.");
          return;
        }
        setEditingPost(post);
      };
    
      const handleUpdateComplete = () => {
        setEditingPost(null);
        fetchPosts();
      };
    
  
    return (
      <div fluid>
        <NavigationBar />
        <Container style={{ width: "100%", paddingTop: "1.5rem" }}>
          <Row>
            <Col style={{ paddingBottom: "1.5rem" }}>
              <h1>Home</h1>
              <Link to="/create">
                <button>Create New Post</button>
              </Link>
            </Col>
          </Row>
          {!editingPost && <PostForm refreshPosts={fetchPosts} />}
          {posts.length > 0 ? (
            posts.map((post) => (
              <Row key={post.id} style={{ backgroundColor: "#282c34", padding: "10px", borderRadius: "30px", marginBottom: "1rem" }}>
                <Col style={{ backgroundColor: "#787878", padding: "15px 30px", borderRadius: "25px" }}>
                  <div>
                    <h4>Posted by: {post.user.username}</h4>
                  </div>
                  <div>
                    <p>{post.content}</p>
                    {Number(userId) === post.user.id && (
                        <div>
                        <button onClick={() => handleEdit(post)}>Edit</button>
                        <button onClick={() => handleDelete(post.id, post.user.id)}>Delete</button>
                        </div>
                    )}
                    {editingPost && editingPost.id === post.id && (
                        <PostForm post={editingPost} refreshPosts={handleUpdateComplete} />
                    )}
                  </div>
                  <div>
                    <p>{post.likes} Likes</p>
                  </div>
                  <div>
                    <Comment postId={post.id} user={currentUser} />
                  </div>
                </Col>
              </Row>
            ))
          ) : (
            <p>No posts available.</p>
          )}
        </Container>
      </div>
    );
  }
  
  export default Home;
